package com.courtstory.app;
import org.junit.Test;
import org.json.*;
import java.util.*;
import static org.junit.Assert.*;
import static com.courtstory.app.Domain.*;
public class ConnectProtocolTest {
 @Test public void strictInvitationOrigin(){String code="a".repeat(64),host="connect.example.invalid";assertEquals(code,ConnectProtocol.code("https://"+host+"/connect/invite#"+code,host));assertEquals(code,ConnectProtocol.code(code,host));for(String bad:new String[]{"http://"+host+"/connect/invite#"+code,"https://evil.example/connect/invite#"+code,"https://user@"+host+"/connect/invite#"+code,"https://"+host+":443/connect/invite#"+code,"https://"+host+"/connect/invite?code="+code,"a".repeat(63)})assertNull(ConnectProtocol.code(bad,host));}
 @Test public void crossPlatformNoteIdentity(){assertEquals("fe1cb8b1-724c-5eaf-b03c-6d003d053b48",ConnectProtocol.noteID("00000000-0000-0000-0000-000000000001"));}
 @Test public void projectionExcludesHealthAndSeparatesNotes(){JSONObject library=obj(),r=obj(),health=obj();String player=id(),record=id();put(r,"id",record);put(r,"playerID",player);put(r,"date","2026-01-01T00:00:00Z");put(r,"setScores","6–4");put(r,"notes","Explicit consent required");put(health,"heartRate",140);put(r,"workout",health);put(r,"media","private-file");put(library,"matches",new JSONArray().put(r));assertTrue(ConnectProtocol.project(library,Set.of()).isEmpty());List<JSONObject> projected=ConnectProtocol.project(library,Set.of(player.toLowerCase(Locale.ROOT)));assertEquals(2,projected.size());JSONObject body=projected.get(0).optJSONObject("p_body");assertFalse(body.has("notes"));assertFalse(body.has("workout"));assertFalse(body.has("media"));assertEquals("6–4",body.optString("score"));assertEquals("note",projected.get(1).optString("p_category"));assertTrue(r.has("workout"));}
 @Test public void futureAndSportScopes(){JSONObject c=obj(),r=obj();put(c,"player_account","owner");put(c,"player_id","player");put(c,"sport","Tennis");put(c,"state","active");put(c,"categories",new JSONArray().put("match"));put(c,"history","future");put(c,"future_sharing",true);put(c,"approved_at","2026-10-01T00:00:00Z");put(r,"p_player","player");put(r,"p_sport","Tennis");put(r,"p_category","match");put(r,"p_occurred","2026-09-01T00:00:00Z");assertFalse(ConnectProtocol.permits(c,r,"owner"));put(r,"p_occurred","2026-10-02T00:00:00Z");assertTrue(ConnectProtocol.permits(c,r,"owner"));put(r,"p_sport","Squash");assertFalse(ConnectProtocol.permits(c,r,"owner"));put(r,"p_sport","Tennis");put(c,"state","revoked");assertFalse(ConnectProtocol.permits(c,r,"owner"));}
 @Test public void shareAllCategoriesRemainUnderOnePlayer(){JSONObject library=obj();String player=id(),other=id();JSONObject match=obj();put(match,"id",id());put(match,"playerID",player);put(match,"date","2020-01-01T00:00:00Z");put(match,"notes","Note");put(match,"matchStory","Sporting reflection");put(match,"nextPracticeFocus","Practice goal");put(match,"playerName","Synthetic player");put(match,"partnerName","Synthetic partner");put(match,"opponentName","Synthetic opponent");JSONObject unrelated=copy(match);put(unrelated,"id",id());put(unrelated,"playerID",other);put(library,"matches",new JSONArray().put(match).put(unrelated));for(String table:new String[]{"trainingSessions","tournaments"}){JSONObject r=obj();put(r,"id",id());put(r,"playerID",player);put(r,"date","2020-01-01T00:00:00Z");put(library,table,new JSONArray().put(r));}List<JSONObject> projected=ConnectProtocol.project(library,Set.of(player.toLowerCase(Locale.ROOT)));Set<String> cats=new HashSet<>(),ids=new HashSet<>();for(JSONObject r:projected){cats.add(r.optString("p_category"));ids.add(r.optString("p_id"));assertEquals(player.toLowerCase(Locale.ROOT),r.optString("p_player"));}assertEquals(new HashSet<>(Arrays.asList(ConnectProtocol.CATEGORIES)),cats);assertEquals(projected.size(),ids.size());JSONArray people=projected.get(0).optJSONArray("p_people");assertEquals(3,people.length());assertEquals(0,people.optJSONObject(1).optInt("team"));assertEquals(1,people.optJSONObject(2).optInt("team"));}
 @Test public void trainingPlanSeparatesSensitiveDetailsAndReview(){JSONObject library=obj(),r=obj(),court=obj(),plan=obj();String player=id();put(r,"id",id());put(r,"playerID",player);put(r,"date","2020-01-01T00:00:00Z");put(plan,"objective","Serve placement");put(plan,"review","Improving");put(plan,"adaptations","Sensitive access information");put(court,"surface","Clay");put(court,"plan",plan);put(r,"court",court);put(library,"trainingSessions",new JSONArray().put(r));List<JSONObject> rows=ConnectProtocol.project(library,Set.of(player.toLowerCase(Locale.ROOT)));JSONObject body=rows.get(0).optJSONObject("p_body");assertEquals("Serve placement",body.optString("planObjective"));assertEquals("Clay",body.optString("surface"));assertFalse(body.has("review"));assertFalse(rows.toString().contains("Sensitive access information"));assertEquals("reflection",rows.get(1).optString("p_category"));}
 @Test public void androidNativePlanFieldsUseSharedProtocol(){JSONObject library=obj(),r=obj();String player=id();put(r,"id",id());put(r,"playerID",player);put(r,"date","2020-01-01T00:00:00Z");put(r,"sessionObjectives","Native plan");put(r,"plannedDrills","Serve targets");put(r,"coachReview","Native review");put(r,"adaptations","Sensitive access detail");put(library,"trainingSessions",new JSONArray().put(r));List<JSONObject> rows=ConnectProtocol.project(library,Set.of(player.toLowerCase(Locale.ROOT)));assertEquals("Native plan",rows.get(0).optJSONObject("p_body").optString("planObjective"));assertEquals("Serve targets",rows.get(0).optJSONObject("p_body").optString("planDrills"));assertEquals("Native review",rows.get(1).optJSONObject("p_body").optString("text"));assertFalse(rows.toString().contains("Sensitive access detail"));}
 @Test public void developmentAndJournalHistoryStayUnderOwner(){JSONObject library=obj(),owner=obj(),other=obj(),note=obj();String player=id();put(owner,"id",player);put(owner,"primaryGoal","Legacy goal");put(owner,"developmentNotes","Improve return placement");put(owner,"health","Sensitive health data");put(note,"id",id());put(note,"date","2020-01-01T00:00:00Z");put(note,"observation","Consistent contact");put(note,"nextAction","Practice returns");put(owner,"coachingJournal",new JSONArray().put(note));put(other,"id",id());put(other,"primaryGoal","Other player's goal");put(library,"players",new JSONArray().put(owner).put(other));String before=library.toString();List<JSONObject> rows=ConnectProtocol.project(library,Set.of(player.toLowerCase(Locale.ROOT)));assertEquals(4,rows.size());for(JSONObject row:rows)assertEquals(player.toLowerCase(Locale.ROOT),row.optString("p_player"));assertTrue(rows.stream().anyMatch(r->r.optString("p_occurred").equals("2020-01-01T00:00:00Z")));assertFalse(rows.toString().contains("Sensitive health data"));assertFalse(rows.toString().contains("Other player's goal"));assertEquals(before,library.toString());}
}
